const getPostPreviewStyleBucket = (style, device, state) => style?.[device]?.[state] ?? {};
const generatePostPreviewElementCSS = (style, device, state) => {
  let styleArr = [];
  if (!style || typeof style !== "object") {
    return "";
  }
  const appendPostPreviewStyles = (deviceKey, stateKey) => {
    const bucket = getPostPreviewStyleBucket(style, deviceKey, stateKey);
    Object.keys(bucket).forEach(item => {
      const filter_item = CamelToSnake(item);
      styleArr = removeDuplicateProperty(styleArr, filter_item);
      if (item != "overlay") {
        const value = bucket[item];
        if (value !== undefined && value !== null && value !== "") {
          styleArr.push(CamelToSnake(item) + ":" + value + ";");
        }
      }
    });
  };
  if (device == "mobile") {
    if (state == "default") {
      appendPostPreviewStyles("desktop", state);
      appendPostPreviewStyles(device, state);
    } else {
      appendPostPreviewStyles("desktop", "default");
      appendPostPreviewStyles("desktop", state);
      appendPostPreviewStyles(device, "default");
      appendPostPreviewStyles(device, state);
    }
  } else if (device == "tablet") {
    if (state == "default") {
      appendPostPreviewStyles("desktop", state);
      appendPostPreviewStyles(device, state);
    } else {
      appendPostPreviewStyles("desktop", "default");
      appendPostPreviewStyles("desktop", state);
      appendPostPreviewStyles(device, "default");
      appendPostPreviewStyles(device, state);
    }
  } else if (device == "desktop") {
    if (state == "default") {
      appendPostPreviewStyles(device, state);
    } else {
      appendPostPreviewStyles(device, "default");
      appendPostPreviewStyles(device, state);
    }
  }
  return normalizeGradientTextStyles(styleArr).join(" ");
};
